BOOL __stdcall BeginCutScene() {
    if (gnRenderState) {
      return 0;
    }

    BOOL bResizeResult = Glide::ResizeWindow((HWND)gnGlideWindowHandle, 0);
    if (!bResizeResult) {
      return 0;
    }

    Glide::SetGamma(100);
    return 1;
}

